import{_ as a,o as e,c as r,ag as l}from"./chunks/framework.CAXxHpAX.js";const q=JSON.parse('{"title":"丹田","description":"","frontmatter":{},"headers":[],"relativePath":"50-概念资料/dict-丹田.md","filePath":"50-概念资料/dict-丹田.md","lastUpdated":1778031108000}'),o={name:"50-概念资料/dict-丹田.md"};function i(d,t,h,n,u,s){return e(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="丹田" tabindex="-1">丹田 <a class="header-anchor" href="#丹田" aria-label="Permalink to &quot;丹田&quot;">​</a></h1><h2 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to &quot;定义&quot;">​</a></h2><p>丹田是丹道修炼中的关键部位，意为&quot;炼丹的田&quot;。了空居士体系中最重要的是<strong>中丹田</strong>（膻中一带），其次是下丹田和上丹田。</p><h2 id="丹田分类" tabindex="-1">丹田分类 <a class="header-anchor" href="#丹田分类" aria-label="Permalink to &quot;丹田分类&quot;">​</a></h2><table tabindex="0"><thead><tr><th>名称</th><th>位置</th><th>了空居士的观点</th></tr></thead><tbody><tr><td>上丹田</td><td>眉心（印堂）</td><td>不建议初学者守上丹田，易头晕</td></tr><tr><td><strong>中丹田</strong></td><td>膻中穴（两乳之间）一带，覆盖整个体腔</td><td>★ 了空居士<strong>最推荐</strong>的观照位置</td></tr><tr><td>下丹田</td><td>肚脐下三寸</td><td>初学者可守，但不如中丹田方便</td></tr></tbody></table><h2 id="了空居士原话" tabindex="-1">了空居士原话 <a class="header-anchor" href="#了空居士原话" aria-label="Permalink to &quot;了空居士原话&quot;">​</a></h2><blockquote><p>&quot;神守黄房，金胎自成。黄房乃乾之下、坤之上。——黄房就是中丹田，轻轻观照中丹田，丹道的基础就自然形成了。&quot;</p></blockquote><blockquote><p>&quot;静坐时轻轻返观整个体腔——膻中到丹田这一片区域，似守非守。&quot;</p></blockquote><h2 id="为什么了空居士最推荐中丹田" tabindex="-1">为什么了空居士最推荐中丹田 <a class="header-anchor" href="#为什么了空居士最推荐中丹田" aria-label="Permalink to &quot;为什么了空居士最推荐中丹田&quot;">​</a></h2><ul><li>不容易出偏（守下丹田有些人会气堵）</li><li>位置在身体中央，容易放松</li><li>覆盖整个体腔，不上火</li></ul><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/50-概念资料/dict-小周天">小周天</a> — 丹田是周天运行的能量核心</li><li><a href="/50-概念资料/dict-大周天">大周天</a> — 全身经脉都与丹田相连</li></ul><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/model-性命双修">性命双修</a></li></ul><h2 id="修行实践" tabindex="-1">修行实践 <a class="header-anchor" href="#修行实践" aria-label="Permalink to &quot;修行实践&quot;">​</a></h2><ul><li>静坐时轻轻返观整个体腔，不要死守一个点</li><li>&quot;似守非守&quot;——守得太紧伤身，守得太松无效</li><li>感觉到温热、发麻都是正常现象</li></ul>',16)])])}const b=a(o,[["render",i]]);export{q as __pageData,b as default};
